/* HR account, system notifications, templates and mail history. */
(function(root){
  const V=HRViews,{e,button,header,badge,empty,select,search}=V;
  const original=V.render;
  const tabs=page=>'<nav class="module-tabs" aria-label="Notification pages">'+[['notifications','Notification Center'],['outbox','Email Outbox'],['templates','Email Templates'],['mail-log','Notification Log']].map(([id,label])=>`<a class="${page===id?'active':''}" href="#/${id}">${label}</a>`).join('')+'</nav>';
  function notifications(db,ui){const items=db.systemNotifications.filter(n=>(ui.noticeTab!=='unread'||!n.read)&&(!ui.noticeType||n.eventType===ui.noticeType)&&(!ui.from||n.createdAt.slice(0,10)>=ui.from)&&(!ui.to||n.createdAt.slice(0,10)<=ui.to)&&(!ui.q||n.title.toLowerCase().includes(ui.q.toLowerCase())));return header('Notification Center','Updates from Applications.',button('system-read-all','Mark all as read'))+tabs('notifications')+`<div class="page-filters">${search(ui.q,'Search updates')}${select('noticeTab',[['all','All updates'],['unread','Unread']],ui.noticeTab,'Read status')}${select('noticeType',[['','All types'],'New Application','Status Update'],ui.noticeType||'','Event type')}<label>From<input type="date" data-filter="from" value="${e(ui.from)}"></label><label>To<input type="date" data-filter="to" value="${e(ui.to)}"></label>${button('clear-filters','Clear filters','','text-button')}</div><section class="panel">${items.length?items.map(n=>`<article class="notification-item ${n.read?'':'unread'}"><span class="icon-disc blue">${icon('bell')}</span><div><strong>${e(n.title)}</strong><small>${e(n.eventType)} · ${V.datetime(n.createdAt)} · ${e(n.sourceModule)}</small></div><div class="card-actions">${V.link('review/'+n.applicationId,'View Application','button secondary compact')}${n.read?badge('Read'):button('system-read','Mark read',n.id,'text-button')}</div></article>`).join(''):empty('No updates found')}</section>`;}
  function outbox(db,ui){const items=db.notifications.filter(n=>(!ui.mailStatus||n.status===ui.mailStatus)&&(!ui.q||(n.subject+' '+n.to).toLowerCase().includes(ui.q.toLowerCase())));return header('Email Outbox','Review candidate messages before sending.')+tabs('outbox')+`<div class="page-filters">${search(ui.q,'Search messages')}${select('mailStatus',[['','All statuses'],'Draft','Sending','Sent','Superseded','Uncertain'],ui.mailStatus||'','Message status')}</div><section class="panel">${items.length?items.map(n=>`<article class="notification-item"><span class="icon-disc blue">${icon('mail')}</span><div><strong>${e(n.subject)}</strong><p>${e(n.to)}</p><small>${V.datetime(n.createdAt)} · ${e(n.status)}</small>${n.lastError?'<p>'+e(n.lastError)+'</p>':''}</div><div class="card-actions">${button('message-edit',n.status==='Draft'?'Review draft':'View message',n.id,'secondary compact')}${n.status==='Draft'?button('mail-send','Send',n.id,'primary compact'):''}</div></article>`).join(''):empty('No messages yet','Prepare a candidate message from an application.')}</section>`;}
  function templates(db,ui){const items=db.templates.filter(t=>t.active&&(!ui.q||(t.name+' '+t.kind).toLowerCase().includes(ui.q.toLowerCase())));return header('Email Templates','Reusable wording for candidate messages.',db.currentUser.role==='HR_MANAGER'?button('template-new','Create Template','','primary'):'')+tabs('templates')+`<div class="page-filters">${search(ui.q,'Search templates')}</div><div class="job-grid">${items.map(t=>`<article class="panel padded"><p class="eyebrow">${e(t.kind)}</p><h3>${e(t.name)}</h3><p>${e(t.subject)}</p><div class="note-box spaced">${e(t.body)}</div><div class="card-actions spaced">${button('template-preview','Preview',t.id,'secondary compact')}${db.currentUser.role==='HR_MANAGER'?button('template-edit','Edit',t.id,'secondary compact')+button('template-delete','Archive',t.id,'text-button'):''}</div></article>`).join('')}</div>`;}
  function mailLog(db,ui){const items=db.mailLogs.filter(n=>(!ui.q||(n.candidateName+' '+n.subject+' '+n.to).toLowerCase().includes(ui.q.toLowerCase()))&&(!ui.from||n.sentAt.slice(0,10)>=ui.from)&&(!ui.to||n.sentAt.slice(0,10)<=ui.to));return header('Notification Log','Messages accepted by the email server; inbox delivery is not tracked.')+tabs('mail-log')+`<div class="page-filters">${search(ui.q,'Search sent messages')}<label>From<input type="date" data-filter="from" value="${e(ui.from)}"></label><label>To<input type="date" data-filter="to" value="${e(ui.to)}"></label>${button('clear-filters','Clear filters','','text-button')}</div><section class="panel">${items.length?`<div class="table-scroll"><table><thead><tr><th>CANDIDATE</th><th>POSITION</th><th>TRIGGER EVENT</th><th>TEMPLATE</th><th>SENT TIME</th><th>ACTION</th></tr></thead><tbody>${items.map(n=>`<tr><td>${e(n.candidateName)}<small>${e(n.to)}</small></td><td>${e(n.jobTitle)}</td><td>${e(n.triggerEvent)}</td><td>${e(n.templateName||'Custom message')}</td><td>${V.datetime(n.sentAt)}</td><td>${button('mail-log-detail','View Details',n.id,'secondary compact')}</td></tr>`).join('')}</tbody></table></div>`:empty('No sent messages','Draft messages are shown in Email Outbox.')}</section>`;}
  function profile(db){const u=db.currentUser;return header('My Profile','HR account information.',button('profile-edit','Edit Profile','','primary')+button('password','Change Password')+button('logout','Sign Out','','secondary'))+`<section class="panel padded hr-profile"><div class="person"><span class="avatar blue">${e(u.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div><h3>${e(u.name)}</h3><p>${u.role==='HR_MANAGER'?'HR Manager':'HR Officer'}</p></div></div><dl class="details spaced">${[['Employee ID',u.employeeId],['Name',u.name],['Work Email',u.email],['Department',u.department],['Account Status',u.status],['Phone',u.phone||'Not provided'],['Office Location',u.officeLocation||'Not provided'],['Time Zone','Asia/Singapore (UTC+08:00)']].map(([label,value])=>`<dt>${label}</dt><dd>${e(value)}</dd>`).join('')}</dl></section>`;}
  V.render=(route,db,ui)=>{if(!db.currentUser)return original(route,db,ui);switch(route[0]){case 'notifications':return notifications(db,ui);case 'outbox':return outbox(db,ui);case 'templates':return templates(db,ui);case 'mail-log':return mailLog(db,ui);case 'hr-profile':return profile(db);default:return original(route,db,ui);}};
  root.HRExtra={
    attach(ctx){const {store,open,form,field,area,choice,render,go,notify,close}=ctx;
      const cFields=c=>field('Full name','name',c?.name||'','text','required maxlength="100"')+field('Email','email',c?.email||'','email','required maxlength="254"')+field('Phone','phone',c?.phone||'','text','required maxlength="40"')+field('Location','location',c?.location||'Singapore','text','required maxlength="100"')+field('Experience (years)','experience',c?.experience??0,'number','required min="0" max="70" step="0.1"')+field('Education','education',c?.education||'','text','required maxlength="150"')+field('Skills (comma separated)','skills',c?.skills?.join(', ')||'','text','required maxlength="500"');
      async function action(action,id){const db=store.db;
        switch(action){
          case 'application-new':open('Receive Application','Record an application received by the HR team.',form('application-create','',choice('Position','jobId',db.jobs.filter(j=>j.status==='Active').map(j=>[j.id,j.title]))+choice('Existing candidate (or enter new details)','candidateId',[['','New candidate'],...db.candidates.map(c=>[c.id,c.name+' · '+c.email])])+'<div data-new-candidate>'+cFields()+'</div>'+choice('Priority','priority',['Normal','High'],'Normal'),'Create Application'),'file','blue',true);break;
          case 'candidate-edit':{const c=db.candidates.find(c=>c.id===id);open('Edit Candidate','Update contact details and experience.',form('candidate-save',id,cFields(c),'Save Candidate'),'user');break;}
          case 'resume-upload':open('Upload Resume','PDF, maximum 5 MB.',`<form class="form" data-command="resume-upload" data-id="${e(id)}"><div class="modal-content"><div class="form-error" role="alert" hidden></div><label>Resume file<input type="file" name="resume" accept=".pdf,application/pdf" required></label></div><footer class="form-footer">${button('close','Cancel')}<button type="submit" class="button primary">Upload Resume</button></footer></form>`,'file');break;
          case 'workspace-refresh':await store.refresh();render();notify('Latest workspace loaded.');break;
          case 'sign-in-again':location.reload();break;
          case 'logout':await store.logout();break;
          case 'profile-edit':open('Edit Profile','Update your contact information.',form('profile-save','',field('Phone','phone',db.currentUser.phone,'text','maxlength="40"')+field('Office location','officeLocation',db.currentUser.officeLocation,'text','maxlength="100"'),'Save Profile'),'user');break;
          case 'password':open('Change Password','You will sign in again after saving.',form('password','',field('Current password','currentPassword','','password','required autocomplete="current-password"')+field('New password','newPassword','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+field('Confirm new password','confirmPassword','','password','required minlength="12" maxlength="128" autocomplete="new-password"'),'Change Password'),'user');break;
          case 'system-read':case 'system-read-all':await store.commit(action,{id});render();break;
          case 'template-new':case 'template-edit':{const t=db.templates.find(t=>t.id===id);open(t?'Edit Template':'Create Template','Variables: {{candidateName}}, {{jobTitle}}, {{hrName}}, {{date}}, {{time}}, {{interviewer}}, {{location}}, {{format}}, {{salary}}, {{currency}}, {{startDate}}, {{expiry}}.',form('template-save',id||'',field('Template name','name',t?.name||'','text','required maxlength="100"')+choice('Type','kind',['Interview Invite','Offer Letter','Accepted','Rejected','In Progress'],t?.kind||'In Progress')+field('Subject','subject',t?.subject||'','text','required maxlength="200"')+area('Message','body',t?.body||'','required maxlength="6000" rows="10"'),'Save Template'),'mail','blue',true);break;}
          case 'template-delete':if(confirm('Archive this template? Existing sent messages will keep their original content.')){await store.commit('template-delete',{id});render();}break;
          case 'template-preview':open('Preview Template','Select the application to fill its variables.',form('template-preview',id,choice('Application','applicationId',db.applications.map(a=>[a.id,V.candidate(db,a).name+' · '+V.job(db,a).title])),'Preview'),'mail');break;
          case 'mail-send':{const n=db.notifications.find(n=>n.id===id),a=db.applications.find(a=>a.id===n.applicationId),c=V.candidate(db,a);open('Send Candidate Email','Review the recipient and message before sending.',form('mail-send',id,`<dl class="details"><dt>To</dt><dd>${e(n.to)}</dd><dt>Subject</dt><dd>${e(n.subject)}</dd></dl><div class="note-box spaced">${e(n.body)}</div>${c.resume?'<label><input type="checkbox" name="attachResume"> Attach the candidate’s uploaded resume</label>':''}${!db.mailEnabled?'<p class="form-error">Email sending has not been configured. This message remains a draft.</p>':''}`,'Send Email'),'mail','blue',true);break;}
          case 'mail-log-detail':{const n=db.mailLogs.find(n=>n.id===id),a=await store.request('hr/mailLogs/'+encodeURIComponent(id)+'/attachments');open('Sent Message','Accepted by the configured email server.',`<div class="modal-content"><dl class="details">${[['Candidate',n.candidateName],['Position',n.jobTitle],['Recipient',n.to],['Trigger event',n.triggerEvent],['Source module',n.sourceModule],['Template',n.templateName||'Custom message'],['Sent time',V.datetime(n.sentAt)],['Sent by',n.actor],['Message ID',n.messageId]].map(([k,v])=>`<dt>${k}</dt><dd>${e(v)}</dd>`).join('')}</dl><h3 class="spaced">${e(n.subject)}</h3><div class="note-box spaced">${e(n.body)}</div>${a.items.map(r=>`<p><a href="/api/hr/attachments/${encodeURIComponent(r.id)}">${e(r.filename)}</a></p>`).join('')}</div>`,'mail','green',true);break;}
          default:return false;
        }return true;
      }
      async function submit(cmd,id,data,f){
        if(cmd==='resume-upload'){await store.upload(id,f.elements.resume.files[0]);close(true);render();notify('Resume uploaded.');return true;}
        if(cmd==='password'){if(data.newPassword!==data.confirmPassword)throw Error('The new passwords do not match.');await store.request('auth/password',{method:'POST',body:{currentPassword:data.currentPassword,newPassword:data.newPassword}});location.reload();return true;}
        if(cmd==='template-preview'){const r=await store.request('hr/templates/'+encodeURIComponent(id)+'/preview',{method:'POST',body:{applicationId:data.applicationId}});open('Template Preview','Candidate-facing content.',`<div class="modal-content"><h3>${e(r.subject)}</h3><div class="note-box spaced">${e(r.body)}</div></div>`,'mail');return true;}
        if(cmd==='mail-send'){try{await store.send(id,!!f.elements.attachResume?.checked);close(true);go('mail-log');notify('The email server accepted the message.');}catch(e){try{await store.refresh();render();}catch{}throw e;}return true;}
        return false;
      }
      return {action,submit};
    }
  };
})(window);
